const req = $('Receive Booking Request').first().json;
const doctors = $('Get Department Doctors').all().map((i) => i.json).filter((d) => d.doctor_id && d.active !== false);
const booked = $('Get Appointments On Date').all().map((i) => i.json).filter((a) => a.slot_key);
const base = { department: req.department, patient_name: req.patient_name, date: req.date, time: req.time, chat_id: req.chat_id };
const done = (status, extra) => [{ json: Object.assign({}, base, { book: false, status: status }, extra || {}) }];

const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(String(req.date || ''));
const timeOk = /^\d{2}:\d{2}$/.test(String(req.time || ''));
if (!req.patient_name || !dateOk || !timeOk) {
  const missing = [];
  if (!req.patient_name) missing.push('name');
  if (!dateOk) missing.push('date');
  if (!timeOk) missing.push('time');
  return done('needs_info', { missing: missing });
}
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' });
if (req.date < today) { return done('past_date'); }
if (!doctors.length) { return done('no_doctor'); }

const dayNumber = new Date(req.date + 'T00:00:00Z').getUTCDay() || 7;
const toMin = (t) => Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5));
const toTime = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const bookedKeys = booked.map((a) => a.slot_key);

const slots = [];
for (const d of doctors) {
  const days = String(d.works_days || '').split(',').map((x) => Number(x.trim()));
  if (!days.includes(dayNumber)) continue;
  for (let m = Number(d.start_hour) * 60; m + Number(d.slot_minutes) <= Number(d.end_hour) * 60; m += Number(d.slot_minutes)) {
    const t = toTime(m);
    slots.push({ doctor_id: d.doctor_id, doctor_name: d.doctor_name, time: t, key: d.doctor_id + '|' + req.date + '|' + t });
  }
}
if (!slots.length) { return done('no_slots_that_day'); }

const duplicate = booked.find((a) => String(a.chat_id) === String(req.chat_id) && a.appt_time === req.time && a.department === req.department);
if (duplicate) {
  return done('already_booked', { appointment_id: duplicate.appointment_id, doctor_name: duplicate.doctor_name });
}

const free = slots.filter((s) => !bookedKeys.includes(s.key));
const exact = free.find((s) => s.time === req.time);
if (exact) {
  const stamp = req.date.replace(/-/g, '') + req.time.replace(':', '');
  const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
  return [{ json: Object.assign({}, base, {
    book: true, status: 'booked',
    appointment_id: 'APT-' + stamp + '-' + rand,
    slot_key: exact.key,
    doctor_id: exact.doctor_id,
    doctor_name: exact.doctor_name,
    phone_masked: '',
    appt_date: req.date,
    appt_time: req.time,
    source: 'telegram'
  }) }];
}
const want = toMin(req.time);
const nearest = free.slice().sort((a, b) => Math.abs(toMin(a.time) - want) - Math.abs(toMin(b.time) - want)).slice(0, 4)
  .sort((a, b) => toMin(a.time) - toMin(b.time));
if (!nearest.length) { return done('fully_booked'); }
return done('time_taken', { alternatives: nearest.map((s) => s.time + ' with ' + s.doctor_name) });
